#!/usr/bin/env bash
# SCRIPT_JDOC: {"summary":"Screen the actual-dispatch opt-in four-column Q4 biased-nibble kernel on frozen ZC1","kind":"mixed","weight":"heavy","role":"entrypoint"}
set -euo pipefail
root=$(cd "$(dirname "$0")/../../.." && pwd)
campaign="$root/benchmarks/intel-1340p/gemma-zc-speed-20260916"
out="$campaign/q4-n4-schedule-screen"
build="$root/build-gemma-zc-speed"
runtime="$root/runtime/gemma-vulkan-f32-0bdd7cd8b/runtime"
model="$root/../models/gemma-4-e4b-qat-mtp/gemma-4-E4B_q4_0-it.gguf"
draft="$root/../models/gemma-4-e4b-qat-mtp/gemma-4-E4B-it-qat-assistant-MTP-Q8_0.gguf"
fixture="$campaign/baseline/sustained-chat-512.json"
production=llama-gemma-zero-copy.service
mkdir -p "$out/runs"
[[ ! -e "$out/complete" ]]
export XDG_RUNTIME_DIR=/run/user/$(id -u) DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/$(id -u)/bus
restore(){ local rc=$?;for u in $(systemctl --user list-units --all --plain --no-legend 'gemma-q4-n4-schedule-*.service' 2>/dev/null|awk '{print $1}');do systemctl --user stop "$u">/dev/null 2>&1||true;systemctl --user reset-failed "$u">/dev/null 2>&1||true;done;systemctl --user start "$production">/dev/null 2>&1||true;local ok=0;for _ in $(seq 1 180);do if curl -fsS http://127.0.0.1:18094/health>"$out/restored-health.json" 2>/dev/null;then ok=1;break;fi;sleep 1;done;systemctl --user show "$production" -p ActiveState -p SubState -p MainPID -p NRestarts -p MemorySwapCurrent -p MemorySwapPeak>"$out/restored-service.txt" 2>&1||true;[[ $ok == 1 ]]||rc=1;exit "$rc";};trap restore EXIT INT TERM
systemctl --user is-active --quiet "$production";[[ $(systemctl --user show whisper-stt.service -p ActiveState --value) == inactive ]];[[ $(systemctl --user show whisper-stt-diarizer.service -p ActiveState --value) == inactive ]];! pgrep -x diar-server>/dev/null;! pgrep -x whisper-cli>/dev/null;[[ $(awk '/MemAvailable:/{print $2}' /proc/meminfo) -ge 12582912 ]];[[ $(find "$build/tools/ui/ui-gzip/_gzip" -type f|wc -l) == 70 ]];systemctl --user stop "$production"
printf 'sequence\tarm\tdecode_tps\twall_s\tprefill_s\tdrafted\taccepted\tgenerated\tshared_bytes\tcopied_bytes\tmemory_peak\tswap_peak\tcontent_sha256\n'>"$out/results.tsv"
run_one(){ local seq=$1 arm=$2;local port=$((19700+seq)) unit="gemma-q4-n4-schedule-${seq}.service" dir="$out/runs/$(printf '%02d-%s' "$seq" "$arm")";mkdir -p "$dir";local envs=(--setenv=LD_LIBRARY_PATH="$build/bin:$runtime" --setenv=GGML_VK_VISIBLE_DEVICES=0 --setenv=GGML_VK_EXPERIMENTAL_ATTN_MODE=f32);if [[ $arm == on ]];then envs+=(--setenv=GGML_CPU_EXPERIMENTAL_Q4_N4_SCHEDULE=1 --setenv=GGML_CPU_Q4_N4_SCHEDULE_TRACE=1);fi
systemd-run --user --unit "$unit" --collect -p Type=simple -p TimeoutStopSec=30 -p MemoryMax=16G -p MemorySwapMax=0 -p TasksMax=256 "${envs[@]}" "$build/bin/llama-gemma-zero-copy-server" --model "$model" --draft "$draft" --alias "gemma-q4-n4-schedule-$arm" --host 127.0.0.1 --port "$port" --ctx-size 32768 --batch-size 256 --ubatch-size 256 --threads 8 --threads-batch 16 --draft-max 3 --draft-min 1 --threadpools 0 --model-sampling 1 --max-output 2048 >"$dir/systemd-run.txt";local ok=0;for _ in $(seq 1 180);do if curl -fsS "http://127.0.0.1:$port/health">"$dir/health.json" 2>/dev/null;then ok=1;break;fi;sleep 1;done;[[ $ok == 1 ]];curl --max-time 180 -fsS "http://127.0.0.1:$port/v1/chat/completions" -H 'Content-Type: application/json' -H "X-Conversation-Id: q4-n4-schedule-$seq" --data-binary @"$fixture">"$dir/response.json";jq -e '.usage.completion_tokens==512 and .choices[0].finish_reason=="length" and .zero_copy.generated_tokens==512 and .zero_copy.drafted==385 and .zero_copy.accepted==382 and .zero_copy.shared_bytes>0 and .zero_copy.copied_bytes==0 and .zero_copy.zero_copy==true' "$dir/response.json";jq -r '.choices[0].message.content' "$dir/response.json"|sha256sum|cut -d' ' -f1>"$dir/content-sha256.txt";systemctl --user show "$unit" -p ActiveState -p SubState -p MainPID -p NRestarts -p MemoryPeak -p MemorySwapPeak>"$dir/service.txt";local swap=$(sed -n 's/^MemorySwapPeak=//p' "$dir/service.txt");[[ $swap == 0 ]];local mem=$(sed -n 's/^MemoryPeak=//p' "$dir/service.txt");journalctl --user -u "$unit" --no-pager>"$dir/journal.txt";if [[ $arm == on ]];then grep -q 'Q4_N4_SCHEDULE m=' "$dir/journal.txt";else ! grep -q 'Q4_N4_SCHEDULE m=' "$dir/journal.txt";fi;printf '%d\t%s\t%.9f\t%.9f\t%.9f\t%d\t%d\t%d\t%d\t%d\t%s\t%s\t%s\n' "$seq" "$arm" "$(jq -r .zero_copy.decode_tps "$dir/response.json")" "$(jq -r .zero_copy.wall_s "$dir/response.json")" "$(jq -r .zero_copy.prefill_s "$dir/response.json")" "$(jq -r .zero_copy.drafted "$dir/response.json")" "$(jq -r .zero_copy.accepted "$dir/response.json")" "$(jq -r .zero_copy.generated_tokens "$dir/response.json")" "$(jq -r .zero_copy.shared_bytes "$dir/response.json")" "$(jq -r .zero_copy.copied_bytes "$dir/response.json")" "$mem" "$swap" "$(cat "$dir/content-sha256.txt")">>"$out/results.tsv";sha256sum "$dir"/* >"$dir/SHA256SUMS";systemctl --user stop "$unit";systemctl --user reset-failed "$unit">/dev/null 2>&1||true;sleep 2;}
run_one 1 off;run_one 2 on;run_one 3 on;run_one 4 off
[[ $(awk -F '\t' 'NR>1{print $13}' "$out/results.tsv"|sort -u|wc -l) == 1 ]];[[ $(awk -F '\t' 'NR>1{print $6"/"$7"/"$8}' "$out/results.tsv"|sort -u|wc -l) == 1 ]];awk -F '\t' 'NR>1{s[$2]+=$3;n[$2]++}END{for(a in s)printf "%s_mean_decode_tps=%.9f\n",a,s[a]/n[a]}' "$out/results.tsv"|sort>"$out/summary.txt";sha256sum "$out/results.tsv" "$out/summary.txt">"$out/SHA256SUMS";touch "$out/complete"
